const options=(items,value)=>items.map(([id,text])=>`<option value="${id}" ${String(id)===String(value)?'selected':''}>${esc(text)}</option>`).join('');
// One shared scale drives both territory fills and the on-screen legend.
const happinessStops=[{value:0,color:'#800020',label:'Very unhappy'},{value:25,color:'#df5446',label:'Unhappy'},{value:50,color:'#f5f3ed',label:'Neutral'},{value:75,color:'#83caff',label:'Happy'},{value:100,color:'#0084ff',label:'Very happy'}];
function happinessColor(value){const n=Math.max(0,Math.min(100,value));const i=Math.min(3,Math.floor(n/25)),a=happinessStops[i],b=happinessStops[i+1],mix=(n-a.value)/(b.value-a.value);const rgb=hex=>[1,3,5].map(j=>parseInt(hex.slice(j,j+2),16));return 'rgb('+rgb(a.color).map((v,j)=>Math.round(v+(rgb(b.color)[j]-v)*mix)).join(',')+')';}
function happinessLegend(){return `<div class="happiness-key"><strong>Happiness heat map</strong><div class="happiness-gradient" aria-hidden="true" style="background:linear-gradient(to right,${happinessStops.map(s=>s.color+' '+s.value+'%').join(',')})"></div><div class="happiness-labels">${happinessStops.map(s=>`<span><b>${s.value}</b><br>${s.label}</span>`).join('')}</div><p>0 = 50% production · 50 = 100% · 100 = 150%. Select a territory for its exact happiness. Water is gray.</p></div>`;}
function fresh(){return DepartmentBudget.init(R.create(generateStudentWorld(crypto.getRandomValues(new Uint32Array(1))[0],GRIA_TEMPLATE)),true);}
function notice(s){$('notice').textContent=s;if($('popupNotice'))$('popupNotice').textContent=s;}
function save(){if(unreadableSave!==null){notice('Autosave paused to protect your unreadable save. Download it, then explicitly open a game or start a new world.');return;}try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notice('Browser storage is full. Download your game before closing.');}}
function change(fn,message){try{const next=structuredClone(state);fn(next);state=DepartmentBudget.record(state,R.validate(next));save();render();if(message)notice(message);return true;}catch(e){notice(e.message);return false;}}
function ask(text,fn,labels={}){pending=fn;$('confirmTitle').textContent=labels.title||'Advance every country?';$('cancel').textContent=labels.cancel||'Keep planning';$('confirmYes').textContent=labels.yes||'Continue';$('confirmText').textContent=text;$('confirm').showModal();}
$('cancel').onclick=()=>{pending=null;$('confirm').close();};$('confirm').oncancel=()=>{pending=null;};$('confirmYes').onclick=()=>{$('confirm').close();const fn=pending;pending=null;fn?.();};
try{const raw=localStorage.getItem(KEY);state=raw?DepartmentBudget.init(R.validate(JSON.parse(raw))):fresh();}catch{unreadableSave=localStorage.getItem(KEY);state=fresh();$('recover').hidden=false;notice('Could not open the saved regiment game. Autosave is paused. Download the unreadable save, then open a backup or start a new world.');}
const living=()=>state.units.filter(u=>u.hp>0),country=id=>state.countries[id]?.name||'Unclaimed';
function phaseInfo(){return {orders:['1 · Plan resources and movement','Economy assigns next-round resources. Military uses delivered funds to recruit and plans movement. New recruits train for one round.','Teacher: move everyone →'],decisions:['2 · Agreements & targets','Movement is complete. Offer and accept alliances now. Attacking breaks trade and research cooperation through the next round. For every contested territory, each country chooses one opponent or hold, then confirms.','Teacher: resolve combat →'],retreat:['3 · Retreat & feed','Military chooses safe retreats. Shared captures need an ownership choice from each participant. Economy must confirm civilian food for every country with land. Finish to deliver budgets, feed armies and collect production.','Teacher: finish retreats & feeding →'],results:['4 · Results','Review captures, income and battle losses. Download pictures; create your own tables and explanations.','Teacher: start next turn →']}[state.phase];}
