 const {c,owned}=foodSummary();tools.innerHTML=`<strong>Territory food plan</strong><p id="foodMapSummary" role="status">${foodSummaryText()}</p><p>Green = fully fed · Orange = partly fed · Red = no food. Click a food marker or your territory to adjust.</p><button id="confirmMapFood" ${c.foodConfirmed?'disabled':''}>${c.foodConfirmed?'Food plan confirmed':'Confirm food plan'}</button>`;$('confirmMapFood').onclick=confirmFoodPlan;
 for(const t of owned){const amount=c.foodPlan[t.id]||0,b=document.createElement('button');b.className='food-pin '+(amount===t.foodNeed?'full':amount?'partial':'empty');b.innerHTML=ResourceUI.icon('food')+`<span>${amount}/${t.foodNeed}</span>`;b.setAttribute('aria-label',`${t.name}: ${amount} of ${t.foodNeed} food. Adjust food`);b.title=t.name;b.style.left=((t.point[0]-camera.x)/camera.w*100)+'%';b.style.top=((t.point[1]-camera.y)/camera.h*100)+'%';b.onclick=()=>{selected=t.id;selectedTroop=null;popupOpen=true;renderTerritoryPopup();$('territoryPopup').focus({preventScroll:true});};markers.append(b);}
